{"python":"import re, math

def norm(x):
    return re.sub(r'[^a-z0-9]+',' ',str(x).lower()).strip()

def truth_bit(v):
    s=str(v).strip().lower()
    if not s or s in ('nan','none'):
        return None
    if 'non-toxic' in s or 'nontoxic' in s or 'no dili' in s or s.startswith('no ') or 'negative' in s:
        return 0
    if 'toxic' in s or 'dili' in s or 'hepatotox' in s:
        return 1
    return None

def num(v):
    if isinstance(v, bool):
        return None
    if isinstance(v,(int,float)) and not (isinstance(v,float) and math.isnan(v)):
        return float(v)
    m=re.search(r'-?\d+(?:\.\d+)?(?:e-?\d+)?', str(v), re.I)
    return float(m.group(0)) if m else None

